head.script:
scwin.screenId = "jldstf07405";

///////// 1. 변수 및 선언 영역 /////////

scwin.grd_Grid = $c.util.getComponent('grd_Grid');

scwin.panel_page = $c.util.getComponent('panel_page');

scwin.grd_List = $c.util.getComponent('grd_List');

scwin.vScrenID = "ULDSTF07405.gfm";

scwin.isSetPopup = false;

scwin.vSelectYear = "";


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.searchCode();
        await scwin.grdSearchCode();
        const firstYear = scwin.dts_BAS_YY.getCellData(1, "VALUE");
        $c.fil.setObjectValue(slc_cmb_BAS_YY, firstYear);
        scwin.vSelectYear = firstYear;
        scwin.fn_list_sync();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07405.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');

scwin.dts_Cod = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Cod')) : $c.util.getComponent('dts_Cod');

scwin.dts_BAS_YY = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_BAS_YY')) : $c.util.getComponent('dts_BAS_YY');

scwin.dts_List2 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List2')) : $c.util.getComponent('dts_List2');

scwin.dts_List3 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List3')) : $c.util.getComponent('dts_List3');

scwin.pMenuID = undefined; try { scwin.pMenuID = /* sdd-asis-lifecycle:begin pMenuID — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.win.getProgramId()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07405' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07405.onpageload' });
    }
};


